\documentclass[tikz,border=5pt]{standalone}
\usepackage{amsmath}
\usetikzlibrary{calc}
\begin{document}
\begin{tikzpicture}[line width=1.1pt, line join=round,
  lbl/.style={font=\fontsize{11.5}{13.8}\selectfont}]
  % Named coordinates (pixel -> units, y flipped, scale 1/100)
  \coordinate (A) at (0,0);
  \coordinate (B) at (7.09,0);
  \coordinate (C) at (7.09,3.54);
  \coordinate (D) at (0,3.54);
  \coordinate (E) at (4.43,4.78);
  \coordinate (N) at (2.65,3.54);
  \coordinate (M) at (3.90,0);
  \coordinate (F) at (6.12,1.41);
  \coordinate (P) at (0,4.94);
  % Fold line endpoints
  \coordinate (FoldTop) at (2.28,4.60);
  \coordinate (FoldBot) at (4.26,-1.05);

  % Rectangle ABCD
  \draw (A) -- (B) -- (C) -- (D) -- cycle;

  % Fold line through N and M
  \draw (FoldTop) -- (FoldBot);

  % Solid segments
  \draw (E) -- (N);
  \draw (E) -- (C);
  \draw (E) -- (F);
  \draw (F) -- (C);
  \draw (F) -- (M);

  % Dashed segments
  \draw[dashed] (D) -- (E);
  \draw[dashed] (A) -- (F);
  \draw[dashed] (F) -- (B);
  \draw[dashed] (D) -- (P);

  % Labels
  \node[lbl, below left] at (A) {$A$};
  \node[lbl, below right] at (B) {$B$};
  \node[lbl, above right] at (C) {$C$};
  \node[lbl, above left] at (D) {$D$};
  \node[lbl, above] at (E) {$E$};
  \node[lbl, below left] at (N) {$N$};
  \node[lbl, below] at (M) {$M$};
  \node[lbl, below right] at (F) {$F$};
  \node[lbl, above left] at (P) {$P$};
\end{tikzpicture}
\end{document}

